    if(kind==="ReturnIcp"){intent.reviewed_amount_e8s=String(args.amount.e8s);intent.reviewed_fee_e8s=String(args.fee.e8s);}
    if(kind==="DisburseStake"){intent.reviewed_amount_e8s=String(observed.disbursementReview.amount);intent.reviewed_fee_e8s=String(observed.disbursementReview.fee);}
    if(["PayConversion","ConvertCycles","CreateCanister"].includes(kind)){intent.reviewed_cycles_fee=String(observed.quote.cyclesFee);intent.reviewed_conversion_rate=String(observed.quote.rate.xdr_permyriad_per_icp);intent.reviewed_quote_timestamp=String(observed.quote.rate.timestamp_seconds);}
