    get plan(){return plan;},get receipt(){return receipt;},get observed(){return observed;},get prepared(){return prepared;},get busy(){return busy;},get manifest(){return manifest;},get recoveryOnly(){return recoveryOnly;},
    hasCapability(profile){try{return !!actorFor(profile);}catch{return false;}},
