      const management=actorFor("ManageBootstrap").management,response=await fetch(manifest.wasm_path,{credentials:"omit",cache:"no-store"});if(!response.ok)throw Error("Certified bootstrap asset is unavailable.");const wasm=new Uint8Array(await response.arrayBuffer());if(sha256Hex(wasm)!==bytesHex(plan.bootstrap_sha256)||wasm.length!==manifest.bytes)throw Error("Recovery upgrade artifact differs from the original approved module.");check();
