      await management.install_code({canister_id:ownCanister(),mode:{upgrade:[]},wasm_module:wasm,arg:IDL.encode([],[]),sender_canister_version:[]});check();await verifyC({installed:true});await management.start_canister({canister_id:ownCanister()});check();const after=await state(),current=await management.canister_status({canister_id:ownCanister()});
