    async cancelCapabilities(){epoch++;if(prepared?.intent.state==="Prepared")settleCreationIntent(receipt,prepared.intent.id,"Rejected");prepared=undefined;await discardCapabilities();notify();},
    async deactivate(){active=false;epoch++;if(prepared?.intent.state==="Prepared")settleCreationIntent(receipt,prepared.intent.id,"Rejected");prepared=undefined;await discardCapabilities();},
    activate(){active=true;epoch++;},
    fundingAccount(){if(!plan)return;const sub=fundingSubaccount(plan.owner,plan.creation_id);return {owner:plan.owner.toText(),subaccount:bytesHex(sub),legacy:bytesHex(legacyAccount(plan.owner,sub))};},
    stakingAccount(){if(!plan||!observed.state||!observed.system?.moduleHash)return;const sub=stakingSubaccount(ownCanister(),plan.nonce);return {owner:governance.toText(),subaccount:bytesHex(sub),legacy:bytesHex(legacyAccount(governance,sub))};},
